PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, username TEXT UNIQUE COLLATE NOCASE, display_username TEXT, bio TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user', suspended INTEGER NOT NULL DEFAULT 0);
CREATE TABLE session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(user_id);
CREATE TABLE account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(provider_id, account_id));
CREATE INDEX account_user ON account(user_id);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE posts (id TEXT PRIMARY KEY, author_id TEXT NOT NULL REFERENCES user(id), root_id TEXT REFERENCES posts(id), parent_id TEXT REFERENCES posts(id), body TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX posts_feed ON posts(root_id, created_at DESC, id DESC);
CREATE INDEX posts_thread ON posts(root_id, created_at, id);
CREATE INDEX posts_author ON posts(author_id, created_at DESC, id DESC);
CREATE TABLE likes (post_id TEXT NOT NULL REFERENCES posts(id), user_id TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, PRIMARY KEY(post_id,user_id));
CREATE TABLE notifications (id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL REFERENCES user(id), actor_id TEXT NOT NULL REFERENCES user(id), post_id TEXT NOT NULL REFERENCES posts(id), kind TEXT NOT NULL CHECK(kind IN ('reply','like')), created_at INTEGER NOT NULL, read_at INTEGER, UNIQUE(recipient_id,actor_id,post_id,kind));
CREATE INDEX notifications_recipient ON notifications(recipient_id, created_at DESC);
CREATE TABLE reports (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), reporter_id TEXT NOT NULL REFERENCES user(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_open_report ON reports(post_id,reporter_id) WHERE status='open';
CREATE TABLE moderation_actions (id TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES user(id), action TEXT NOT NULL, target_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE memberships (user_id TEXT PRIMARY KEY REFERENCES user(id), github_id TEXT NOT NULL, state TEXT NOT NULL, checked_at INTEGER NOT NULL, retry_after INTEGER NOT NULL DEFAULT 0);
CREATE TABLE link_previews (id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', site TEXT NOT NULL DEFAULT '', image TEXT, video_id TEXT, checked_at INTEGER NOT NULL);
CREATE TABLE post_links (post_id TEXT NOT NULL REFERENCES posts(id), preview_id TEXT NOT NULL REFERENCES link_previews(id), position INTEGER NOT NULL, PRIMARY KEY(post_id,preview_id));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
